def send_completion(
    model_name,
    messages,
    functions,
    stream,
    temperature=0,
    extra_headers=None,
    max_tokens=None,
):
    from aider.llm import litellm


    kwargs = dict(
        model=model_name,
        messages=messages,
        stream=stream,
